<?php
namespace Database\Seeders;
use App\Models\{InventoryItem,InventoryStock,Outlet,Property,Store,Supplier};use Illuminate\Database\Seeder;
class HotelProcurementSeeder extends Seeder{public function run():void{$p=Property::first();if(!$p)return;$stores=[['Main Store','MAIN','main'],['Kitchen Store','KITCHEN','kitchen'],['Main Bar Store','BAR','bar'],['Housekeeping Store','HOUSE','housekeeping']];foreach($stores as [$name,$code,$type])Store::firstOrCreate(['property_id'=>$p->id,'code'=>$code],['name'=>$name,'type'=>$type,'is_active'=>true]);Supplier::firstOrCreate(['property_id'=>$p->id,'name'=>'Sample Hotel Supplies Ltd'],['contact_person'=>'Sales Desk','phone'=>'+256700000000','credit_days'=>30]);$main=Store::where('property_id',$p->id)->where('code','MAIN')->first();$kitchen=Store::where('property_id',$p->id)->where('code','KITCHEN')->first();$bar=Store::where('property_id',$p->id)->where('code','BAR')->first();foreach(InventoryItem::where('property_id',$p->id)->get() as $item){$store=$item->kind==='beverage'?$bar:(in_array($item->kind,['food','ingredient'],true)?$kitchen:$main);if($store)InventoryStock::firstOrCreate(['property_id'=>$p->id,'store_id'=>$store->id,'inventory_item_id'=>$item->id],['quantity'=>$item->quantity_on_hand]);}Outlet::where('property_id',$p->id)->where('type','restaurant')->update(['store_id'=>$kitchen?->id]);Outlet::where('property_id',$p->id)->where('type','bar')->update(['store_id'=>$bar?->id]);}}
